# -------------------- Unit Tests: Taxonomy --------------------

class TestTaxonomyLoading:
    """Validate _load_taxonomy behavior."""

    def test_taxonomy_contains_expected_categories(self, analyzer):
        """Core taxonomy keys must exist."""
        assert "deep_learning" in analyzer.taxonomy
        assert "reinforcement_learning" in analyzer.taxonomy

    def test_taxonomy_values_are_lists_of_strings(self, analyzer):
        """All taxonomy entries must be lists of lowercase strings."""
        for category, keywords in analyzer.taxonomy.items():
            assert isinstance(keywords, list)
            assert all(isinstance(k, str) and k.islower() for k in keywords)

    def test_taxonomy_no_empty_categories(self, analyzer):
        """No category should have an empty keyword list."""
        for category, keywords in analyzer.taxonomy.items():
            assert len(keywords) > 0, f"Empty taxonomy for {category}"

    def test_taxonomy_no_duplicate_keywords(self, analyzer):
        """Keywords should be unique across all categories."""
        all_keywords = [kw for kws in analyzer.taxonomy.values() for kw in kws]
        duplicates = [kw for kw, count in Counter(all_keywords).items() if count > 1]
        assert not duplicates, f"Duplicate taxonomy keywords: {duplicates}"

