# -------------------- Property-Based Tests --------------------

class TestKeywordExtractionProperties:
    """Hypothesis-based stability checks."""

    @given(st.text(alphabet=st.characters(blacklist_categories=('Cs',)), min_size=0, max_size=200))
    def test_extract_keywords_never_raises(self, analyzer, text):
        """Any text input must not raise exceptions."""
        try:
            result = analyzer.extract_keywords(text)
            assert isinstance(result, list)
        except Exception as e:
            pytest.fail(f"extract_keywords raised for input {text!r}: {e}")

    @given(st.lists(st.text(min_size=1, max_size=50), min_size=1, max_size=10))
    def test_extract_keywords_deterministic(self, analyzer, texts):
        """Same input must produce same output (no randomness)."""
        for text in texts:
            result1 = analyzer.extract_keywords(text)
            result2 = analyzer.extract_keywords(text)
            assert result1 == result2

    @given(st.text(min_size=1, max_size=100))
    def test_extract_keywords_subset_of_tokens(self, analyzer, text):
        """Extracted keywords must be substrings of the input (or derived)."""
        result = analyzer.extract_keywords(text)
        for kw in result:
            # Keywords may be n-grams, so check token-level containment
            assert any(kw in text.lower() for kw in [kw]) or kw in text.lower()

